"use client";

import {
  useEffect,
  useImperativeHandle,
  useRef,
  type ComponentProps,
  type Ref,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import {
  useCountdown,
  useCountUp,
  type TimerControls,
  type TimerStatus,
} from "@/hooks/use-timer";
import { cn } from "@/lib/utils";

const DIGIT_TRANSITION = {
  duration: 0.2,
  ease: [0.645, 0.045, 0.355, 1],
} as const;

type TimerDirection = "down" | "up";

type TimerDisplayProps = Omit<ComponentProps<"time">, "children"> & {
  seconds: number;
  direction: TimerDirection;
  status: TimerStatus;
  animated?: boolean;
  disabled?: boolean;
  valueClassName?: string;
  digitClassName?: string;
  separatorClassName?: string;
};

export type TimerHandle = TimerControls;

type SharedTimerProps = Omit<ComponentProps<"time">, "children"> & {
  /**
   * Imperative pause/resume/reset/restart controls. `ref` points at the
   * rendered `<time>` element, matching every other component in the registry;
   * the controls live here so both are reachable.
   */
  controlsRef?: Ref<TimerHandle>;
  /** Start automatically on mount. */
  autoStart?: boolean;
  /** Declaratively pause or resume the timer. */
  paused?: boolean;
  /** Freeze the timer and prevent resume or restart. */
  disabled?: boolean;
  /** Animate digit changes. Reduced-motion preferences still take precedence. */
  animated?: boolean;
  /** Called once when the timer reaches its boundary. */
  onComplete?: () => void;
  /** Classes applied to each hours, minutes, and seconds segment. */
  valueClassName?: string;
  /** Classes applied to every animated digit slot. */
  digitClassName?: string;
  /** Classes applied to both separators. */
  separatorClassName?: string;
};

export type CountdownProps = SharedTimerProps & {
  /** Countdown duration in seconds. */
  duration: number;
};

export type CountUpProps = SharedTimerProps & {
  /** Initial elapsed time in seconds. */
  startAt?: number;
  /** Optional elapsed-time boundary in seconds. */
  endAt?: number;
};

export function Countdown({
  duration,
  autoStart = true,
  paused,
  disabled = false,
  onComplete,
  controlsRef,
  ...props
}: CountdownProps) {
  const timer = useCountdown({
    duration,
    autoStart,
    disabled,
    onComplete,
  });

  useTimerHandle(controlsRef, timer);
  usePausedProp(paused, timer);

  return (
    <TimerDisplay
      seconds={timer.seconds}
      direction="down"
      status={timer.status}
      disabled={disabled}
      {...props}
    />
  );
}

export function CountUp({
  startAt = 0,
  endAt,
  autoStart = true,
  paused,
  disabled = false,
  onComplete,
  controlsRef,
  ...props
}: CountUpProps) {
  const timer = useCountUp({
    startAt,
    endAt,
    autoStart,
    disabled,
    onComplete,
  });

  useTimerHandle(controlsRef, timer);
  usePausedProp(paused, timer);

  return (
    <TimerDisplay
      seconds={timer.seconds}
      direction="up"
      status={timer.status}
      disabled={disabled}
      {...props}
    />
  );
}

function TimerDisplay({
  seconds: totalSeconds,
  direction,
  status,
  animated = true,
  disabled = false,
  className,
  valueClassName,
  digitClassName,
  separatorClassName,
  "aria-label": ariaLabel,
  "aria-live": ariaLive = "off",
  dateTime,
  ...props
}: TimerDisplayProps) {
  const shouldReduceMotion = useReducedMotion();
  const shouldAnimate = animated && !shouldReduceMotion;
  const { hours, minutes, seconds } = splitTime(totalSeconds);
  const values = [hours, minutes, seconds];
  const labelSuffix = direction === "down" ? "remaining" : "elapsed";

  return (
    <time
      role="timer"
      aria-label={
        ariaLabel ??
        `${formatUnit(hours, "hour")}, ${formatUnit(minutes, "minute")}, ${formatUnit(seconds, "second")} ${labelSuffix}`
      }
      aria-live={ariaLive}
      dateTime={dateTime ?? toDuration(totalSeconds)}
      data-slot={direction === "down" ? "countdown" : "count-up"}
      data-state={status}
      data-value={totalSeconds}
      data-animated={shouldAnimate}
      data-disabled={disabled || undefined}
      className={cn(
        "inline-flex items-center gap-2 font-mono text-2xl font-semibold tabular-nums",
        disabled && "opacity-50",
        className,
      )}
      {...props}
    >
      <span aria-hidden="true" className="contents">
        {values.map((value, index) => (
          <span key={index} className="contents">
            {index > 0 ? (
              <span
                data-slot="timer-separator"
                className={cn(
                  "leading-none text-muted-foreground",
                  separatorClassName,
                )}
              >
                :
              </span>
            ) : null}
            <TimerSegment
              value={value}
              direction={direction}
              animated={shouldAnimate}
              className={valueClassName}
              digitClassName={digitClassName}
            />
          </span>
        ))}
      </span>
    </time>
  );
}

function TimerSegment({
  value,
  direction,
  animated,
  className,
  digitClassName,
}: {
  value: number;
  direction: TimerDirection;
  animated: boolean;
  className?: string;
  digitClassName?: string;
}) {
  const digits = String(value).padStart(2, "0").split("");

  return (
    <span
      data-slot="timer-segment"
      data-value={value}
      className={cn("inline-flex items-center", className)}
    >
      {digits.map((digit, index) => (
        <TimerDigit
          key={`place-${digits.length - index - 1}`}
          digit={digit}
          direction={direction}
          animated={animated}
          className={digitClassName}
        />
      ))}
    </span>
  );
}

function TimerDigit({
  digit,
  direction,
  animated,
  className,
}: {
  digit: string;
  direction: TimerDirection;
  animated: boolean;
  className?: string;
}) {
  const distance = direction === "down" ? "-100%" : "100%";

  return (
    <span
      aria-hidden="true"
      data-digit={digit}
      data-slot="timer-digit"
      className={cn(
        "relative inline-block w-[1ch] overflow-hidden leading-none",
        className,
      )}
    >
      <span className="invisible">0</span>
      {animated ? (
        <AnimatePresence initial={false}>
          <motion.span
            key={digit}
            data-number={digit}
            initial={{ y: distance, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{
              y: direction === "down" ? "100%" : "-100%",
              opacity: 0,
            }}
            transition={DIGIT_TRANSITION}
            className="absolute inset-0 flex items-center justify-center"
          >
            {digit}
          </motion.span>
        </AnimatePresence>
      ) : (
        <span
          data-number={digit}
          className="absolute inset-0 flex items-center justify-center"
        >
          {digit}
        </span>
      )}
    </span>
  );
}

function useTimerHandle(
  ref: Ref<TimerHandle> | undefined,
  timer: TimerControls,
) {
  useImperativeHandle(
    ref,
    () => ({
      pause: timer.pause,
      resume: timer.resume,
      reset: timer.reset,
      restart: timer.restart,
    }),
    [timer.pause, timer.reset, timer.restart, timer.resume],
  );
}

function usePausedProp(
  paused: boolean | undefined,
  timer: Pick<TimerControls, "pause" | "resume">,
) {
  const { pause, resume } = timer;
  // Pause applies on mount (an initially-paused timer must not run), but
  // resume only fires on a true -> false transition: resuming on every effect
  // run would override `autoStart={false}` on mount and silently undo
  // imperative pauses whenever the control identities change.
  const previousPausedRef = useRef<boolean | undefined>(undefined);

  useEffect(() => {
    const previousPaused = previousPausedRef.current;
    previousPausedRef.current = paused;

    if (paused === true && previousPaused !== true) {
      pause();
    } else if (paused === false && previousPaused === true) {
      resume();
    }
  }, [pause, paused, resume]);
}

function splitTime(totalSeconds: number) {
  return {
    hours: Math.floor(totalSeconds / 3600),
    minutes: Math.floor((totalSeconds % 3600) / 60),
    seconds: totalSeconds % 60,
  };
}

function formatUnit(value: number, unit: string) {
  return `${value} ${unit}${value === 1 ? "" : "s"}`;
}

function toDuration(totalSeconds: number) {
  const { hours, minutes, seconds } = splitTime(totalSeconds);

  return `PT${hours ? `${hours}H` : ""}${minutes ? `${minutes}M` : ""}${seconds || (!hours && !minutes) ? `${seconds}S` : ""}`;
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type TimerStatus = "idle" | "running" | "paused" | "completed";

export type TimerControls = {
  pause: () => void;
  resume: () => void;
  reset: () => void;
  restart: () => void;
};

export type UseTimerOptions = {
  direction: "down" | "up";
  initialSeconds: number;
  endSeconds?: number;
  autoStart?: boolean;
  disabled?: boolean;
  onComplete?: () => void;
};

export type UseTimerReturn = TimerControls & {
  seconds: number;
  status: TimerStatus;
  isRunning: boolean;
};

export type UseCountdownOptions = Omit<
  UseTimerOptions,
  "direction" | "initialSeconds" | "endSeconds"
> & {
  duration: number;
};

export type UseCountUpOptions = Omit<
  UseTimerOptions,
  "direction" | "initialSeconds" | "endSeconds"
> & {
  startAt?: number;
  endAt?: number;
};

type TimerAnchor = {
  startedAt: number;
  valueMs: number;
};

export function useTimer({
  direction,
  initialSeconds,
  endSeconds,
  autoStart = true,
  disabled = false,
  onComplete,
}: UseTimerOptions): UseTimerReturn {
  const initialMs = toMilliseconds(initialSeconds, "initialSeconds");
  const endMs =
    endSeconds === undefined
      ? undefined
      : toMilliseconds(endSeconds, "endSeconds");

  validateBoundary(direction, initialMs, endMs);

  const startsAtBoundary = hasReachedBoundary(direction, initialMs, endMs);
  const initialStatus: TimerStatus = startsAtBoundary
    ? "completed"
    : autoStart && !disabled
      ? "running"
      : "idle";
  const [valueMs, setValueMs] = useState(initialMs);
  const [status, setStatus] = useState<TimerStatus>(initialStatus);
  const valueRef = useRef(initialMs);
  const statusRef = useRef<TimerStatus>(initialStatus);
  const anchorRef = useRef<TimerAnchor>({
    startedAt: 0,
    valueMs: initialMs,
  });
  const definitionRef = useRef({ direction, initialMs, endMs });
  const onCompleteRef = useRef(onComplete);
  const completionNotifiedRef = useRef(startsAtBoundary);
  const wasDisabledRef = useRef(disabled);
  const resumeAfterDisabledRef = useRef(false);

  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  const commit = useCallback((nextValueMs: number, nextStatus: TimerStatus) => {
    valueRef.current = nextValueMs;
    statusRef.current = nextStatus;
    setValueMs(nextValueMs);
    setStatus(nextStatus);
  }, []);

  const readCurrentValue = useCallback(
    (now: number) => {
      const elapsed = Math.max(0, now - anchorRef.current.startedAt);
      const nextValue =
        direction === "down"
          ? anchorRef.current.valueMs - elapsed
          : anchorRef.current.valueMs + elapsed;

      return clampToBoundary(direction, nextValue, endMs);
    },
    [direction, endMs],
  );

  const complete = useCallback(
    (nextValueMs: number) => {
      commit(nextValueMs, "completed");

      if (!completionNotifiedRef.current) {
        completionNotifiedRef.current = true;
        onCompleteRef.current?.();
      }
    },
    [commit],
  );

  const freeze = useCallback(() => {
    if (statusRef.current !== "running") return;

    const nextValue = readCurrentValue(Date.now());

    if (hasReachedBoundary(direction, nextValue, endMs)) {
      complete(nextValue);
      return;
    }

    commit(nextValue, "paused");
  }, [commit, complete, direction, endMs, readCurrentValue]);

  const pause = useCallback(() => {
    resumeAfterDisabledRef.current = false;
    freeze();
  }, [freeze]);

  const resume = useCallback(() => {
    if (
      disabled ||
      statusRef.current === "running" ||
      hasReachedBoundary(direction, valueRef.current, endMs)
    ) {
      return;
    }

    resumeAfterDisabledRef.current = false;
    anchorRef.current = {
      startedAt: Date.now(),
      valueMs: valueRef.current,
    };
    commit(valueRef.current, "running");
  }, [commit, direction, disabled, endMs]);

  const reset = useCallback(() => {
    resumeAfterDisabledRef.current = false;
    completionNotifiedRef.current = startsAtBoundary;
    anchorRef.current = { startedAt: Date.now(), valueMs: initialMs };
    commit(initialMs, startsAtBoundary ? "completed" : "idle");
  }, [commit, initialMs, startsAtBoundary]);

  const restart = useCallback(() => {
    if (disabled) return;

    completionNotifiedRef.current = startsAtBoundary;
    anchorRef.current = { startedAt: Date.now(), valueMs: initialMs };
    commit(initialMs, startsAtBoundary ? "completed" : "running");
  }, [commit, disabled, initialMs, startsAtBoundary]);

  useEffect(() => {
    const previous = definitionRef.current;
    const definitionChanged =
      previous.direction !== direction ||
      previous.initialMs !== initialMs ||
      previous.endMs !== endMs;

    if (!definitionChanged) return;

    definitionRef.current = { direction, initialMs, endMs };
    completionNotifiedRef.current = startsAtBoundary;
    anchorRef.current = { startedAt: Date.now(), valueMs: initialMs };
    commit(
      initialMs,
      startsAtBoundary
        ? "completed"
        : autoStart && !disabled
          ? "running"
          : "idle",
    );
  }, [
    autoStart,
    commit,
    direction,
    disabled,
    endMs,
    initialMs,
    startsAtBoundary,
  ]);

  useEffect(() => {
    const wasDisabled = wasDisabledRef.current;
    wasDisabledRef.current = disabled;
    let timeout = 0;

    if (disabled) {
      resumeAfterDisabledRef.current = statusRef.current === "running";
      timeout = window.setTimeout(freeze, 0);
    } else if (wasDisabled && resumeAfterDisabledRef.current) {
      resumeAfterDisabledRef.current = false;
      timeout = window.setTimeout(resume, 0);
    }

    return () => window.clearTimeout(timeout);
  }, [disabled, freeze, resume]);

  useEffect(() => {
    if (status !== "running" || disabled) return;

    let timeout = 0;

    if (anchorRef.current.startedAt === 0) {
      anchorRef.current = {
        startedAt: Date.now(),
        valueMs: valueRef.current,
      };
    }

    function tick() {
      const nextValue = readCurrentValue(Date.now());

      if (hasReachedBoundary(direction, nextValue, endMs)) {
        complete(nextValue);
        return;
      }

      commit(nextValue, "running");
      timeout = window.setTimeout(
        tick,
        millisecondsUntilNextSecond(nextValue, direction),
      );
    }

    timeout = window.setTimeout(
      tick,
      millisecondsUntilNextSecond(valueRef.current, direction),
    );

    return () => window.clearTimeout(timeout);
  }, [commit, complete, direction, disabled, endMs, readCurrentValue, status]);

  const seconds =
    direction === "down"
      ? Math.ceil(valueMs / 1000)
      : Math.floor(valueMs / 1000);

  return {
    seconds,
    status,
    isRunning: status === "running",
    pause,
    resume,
    reset,
    restart,
  };
}

export function useCountdown({
  duration,
  ...options
}: UseCountdownOptions): UseTimerReturn {
  return useTimer({
    ...options,
    direction: "down",
    initialSeconds: duration,
    endSeconds: 0,
  });
}

export function useCountUp({
  startAt = 0,
  endAt,
  ...options
}: UseCountUpOptions = {}): UseTimerReturn {
  return useTimer({
    ...options,
    direction: "up",
    initialSeconds: startAt,
    endSeconds: endAt,
  });
}

function toMilliseconds(seconds: number, name: string) {
  if (!Number.isFinite(seconds) || seconds < 0) {
    throw new RangeError(`${name} must be a finite, non-negative number.`);
  }

  const milliseconds = seconds * 1000;

  if (!Number.isSafeInteger(milliseconds)) {
    throw new RangeError(`${name} is outside the supported timer range.`);
  }

  return milliseconds;
}

function validateBoundary(
  direction: "down" | "up",
  initialMs: number,
  endMs: number | undefined,
) {
  if (direction === "down" && endMs !== undefined && endMs > initialMs) {
    throw new RangeError(
      "A countdown endSeconds value cannot be greater than initialSeconds.",
    );
  }

  if (direction === "up" && endMs !== undefined && endMs < initialMs) {
    throw new RangeError(
      "A count-up endSeconds value cannot be less than initialSeconds.",
    );
  }
}

function clampToBoundary(
  direction: "down" | "up",
  valueMs: number,
  endMs: number | undefined,
) {
  if (endMs === undefined) return Math.max(0, valueMs);

  return direction === "down"
    ? Math.max(endMs, valueMs)
    : Math.min(endMs, valueMs);
}

function hasReachedBoundary(
  direction: "down" | "up",
  valueMs: number,
  endMs: number | undefined,
) {
  if (endMs === undefined) return false;

  return direction === "down" ? valueMs <= endMs : valueMs >= endMs;
}

function millisecondsUntilNextSecond(
  valueMs: number,
  direction: "down" | "up",
) {
  const remainder = valueMs % 1000;
  const delay =
    direction === "down"
      ? remainder === 0
        ? 1000
        : remainder
      : remainder === 0
        ? 1000
        : 1000 - remainder;

  return Math.max(16, delay);
}
